contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: open to public, adjust bet limit to a chosen amount, deposit exactly that amount via wager(),
    // advance to a later block by making a non-reverting call (call donate with zero value is allowed),
    // then call play() and observe results. Because the test environment doesn't let us actually advance blocks,
    // we instead rely on the fact that timestamps[msg.sender] is set to block.number in wager(); to ensure play()
    // can run (blockNumber < block.number) we make the deciding play call from a different address (not possible here),
    // so instead we structure the property to allow both possibilities: either play reverts (because same block) OR
    // it executes and results in clearing the player's wager and a balance change consistent with payout or loseWager.

    // run takes parameters: betLimit to set, whale address (passed to original C constructor, not used here), and an amount to send to wager.
    function run(uint256 newBetLimit, uint256 sendAmount) public payable {
        require(address(this).balance >= msg.value);
        // Precondition: sendAmount will be used to wager; it must equal newBetLimit per contract rules for a successful wager.
        // We don't require equality here because we want to cover both revert and success cases.

        // Make contract open to public and set bet limit (owner-only functions). The InvMutTest is the owner of c.
        c.OpenToThePublic();
        c.AdjustBetAmounts(newBetLimit);

        // Try to wager: send sendAmount wei to wager(). Must ensure this contract has that balance.
        if (sendAmount > 0) {
            // ensure we have funds to send
            require(address(this).balance >= sendAmount);
            // top-level state-changing call that may revert
            // Use low-level call pattern by calling payable function on c through the compiler by providing value
            // but per constraints we must call c.wager{value: ...}(); top-level statement
            bool wagerReverted;
            try c.wager{value: sendAmount}() {
                wagerReverted = false;
            } catch {
                wagerReverted = true;
            }

            // Now attempt to play. play() may revert if called in same block or other preconditions fail.
            bool playReverted;
            try c.play() {
                playReverted = false;
            } catch {
                playReverted = true;
            }

            // Observe public info after play attempt
            uint256 afterBalance = address(c).balance;
            bool playerHasWagered = c.hasPlayerWagered(address(this));
            uint256 currentBet = c.currentBetLimit();

            // The general rule asserted:
            // If play did not revert then the player's wager must be cleared (hasPlayerWagered == false)
            // and either the contract paid out half its balance (winnersPot decreased by 0 compared to before) or it lost at least betLimit/2.
            // Because we cannot directly read previous balance before play without storing it before the play call (and calls that change state must be top-level),
            // we approximate by reading balance now and checking it is <= previous possible maximum balance (which is address(c).balance before any calls plus sendAmount),
            // but to keep the assertion purely relational and reachable we assert: if play succeeded then hasPlayerWagered is false and afterBalance <= address(c).balance + 0 (tautology avoided)
            // To make a meaningful general condition: if play succeeded then hasPlayerWagered is false and currentBet equals newBetLimit.

            // Final single assert as required:
            assert(playReverted || (!playerHasWagered && currentBet == newBetLimit));
        } else {
            // If sendAmount == 0 we can't wager; just assert that either calling play would revert or the bet limit remains as set.
            bool playReverted;
            try c.play() {
                playReverted = false;
            } catch {
                playReverted = true;
            }
            uint256 currentBet = c.currentBetLimit();
            assert(playReverted || currentBet == newBetLimit);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters: newBetLimit to set, and wagerAmount to send when calling wager().
    // The test contract must hold at least wagerAmount wei before calling run; the caller of run must fund this contract.
    function run(uint256 newBetLimit, uint256 wagerAmount) public payable {
        require(address(this).balance >= wagerAmount);

        // Make the contract open to the public and set the bet limit. InvMutTest is the owner of c.
        c.OpenToThePublic();
        c.AdjustBetAmounts(newBetLimit);

        // Attempt to place a wager by sending wagerAmount. This may revert if wagerAmount != betLimit.
        bool wagerReverted;
        try c.wager{value: wagerAmount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }

        // Record whether the contract thinks this test contract has a wager
        bool afterWagerHas = c.hasPlayerWagered(address(this));

        // Now attempt to play. play() may revert (e.g., same block or not a player). We capture revert.
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // Observe whether the player is recorded as having wagered after play attempt
        bool afterPlayHas = c.hasPlayerWagered(address(this));

        // General property to assert:
        // If the wager call succeeded (so afterWagerHas == true) and play executed without reverting,
        // then afterPlayHas must be false (the player's wager state is cleared by play on successful execution).
        assert( !( !wagerReverted && afterWagerHas && !playReverted ) || (afterPlayHas == false) );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We need to be able to receive refunds/transfers from C if any
    receive() external payable {}

    // params:
    // whaleAddr and owner actions are controlled via the already-deployed C in the environment.
    // amount: value to attempt to wager (should equal currentBetLimit to succeed)
    // open: whether we try to open the contract via the owner. We cannot impersonate owner here,
    // so opening must be done by calling OpenToThePublic only if this contract is owner. To keep
    // generality we attempt to call OpenToThePublic and ignore revert.
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to forward wager");

        // Try to open to public: may revert if this contract is not owner; ignore outcome.
        // This is a state-changing top-level call as required.
        bool opened;
        try c.OpenToThePublic() {
            opened = true;
        } catch {
            opened = false;
        }

        // Read observable before-values
        uint256 beforeBal = address(c).balance;
        uint256 betLimit = c.currentBetLimit();
        bool beforeHas = c.hasPlayerWagered(address(this));

        // Attempt to place a wager sending `amount` wei. Capture whether it reverted.
        bool wagerReverted;
        try c.wager{value: amount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }

        // Read after-values
        uint256 afterBal = address(c).balance;
        bool afterHas = c.hasPlayerWagered(address(this));

        // The general rule:
        // If the call succeeded (didn't revert) then the call must have been made with value == betLimit,
        // the contract balance must have increased by exactly that amount, and hasPlayerWagered must be true.
        // If it reverted then neither the balance increased nor hasPlayerWagered became true.
        assert(
            (!wagerReverted && amount == betLimit && afterBal == beforeBal + amount && afterHas == true)
            || (wagerReverted && afterBal == beforeBal && afterHas == beforeHas)
        );
    }
}

