contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test that when the contract is opened to public by its owner (which is the deployer of C),
    // a call to wager from this test contract with a provided amount succeeds exactly when amount == c.currentBetLimit(),
    // and in that case hasPlayerWagered(address(this)) becomes true. If the amount != betLimit the call must revert and hasPlayerWagered stays false.
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test send");

        // Open to public: onlyOwner on C will succeed because the owner of C is its deployer (the environment),
        // but the checker deploys a fresh C and provides it to this test; we cannot assume this contract is owner.
        // However, contract C exposes OpenToThePublic() as onlyOwner. To make a valid owner call we use try/catch and treat failure as allowed.
        // The property we assert will be conditional on whether OpenToThePublic succeeded.
        bool opened = false;
        try c.OpenToThePublic() {
            opened = true;
        } catch {
            opened = false;
        }

        // Read current bet limit regardless
        uint256 currentLimit = c.currentBetLimit();
        bool reverted = false;
        // attempt to wager with this contract as sender and sending 'amount'
        try c.wager{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe whether this contract is recorded as having wagered
        bool recorded = c.hasPlayerWagered(address(this));

        // General rule asserted below:
        // If the contract was opened to public, then the wager call should succeed (not reverted) and be recorded iff amount == currentLimit.
        // If not opened, then wager must revert and not be recorded.
        assert(
            opened ? ((reverted == (amount != currentLimit)) && (recorded == (!reverted))) : (reverted == true && recorded == false)
        );
    }

    // Allow receiving Ether so the test contract can hold funds to send
    receive() external payable {}
}

