contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept two params: amount to donate and a bitflag to first open the contract to public.
    // The test will: optionally call OpenToThePublic (so donate is allowed), ensure this contract
    // has enough ETH, then call c.donate{value: amount}(), and assert the relation between
    // balances when the call succeeds (non-revert).
    function run(uint256 amount, bool openPublic) public payable {
        require(address(this).balance >= amount);

        // If requested, open the contract to the public so donate() won't revert due to isOpenToPublic
        if (openPublic) {
            // onlyOwner modifier requires msg.sender == owner; the owner is the deployer of C.
            // The checker deploys a fresh C and passes it to this test's constructor, so this contract
            // is NOT the owner; therefore we cannot call OpenToThePublic unless this contract is owner.
            // To satisfy the constraint that all state-changing calls must be top-level, and since we
            // cannot know whether we are owner, we instead conservatively require openPublic to be false
            // unless this contract actually is the owner. We perform a try/catch to detect ownership by
            // attempting to call OpenToThePublic and observing revert. However, state-changing calls
            // must be top-level statements; try/catch is permitted but the template disallowed nesting
            // of state-changing calls inside try; however top-level try is still a top-level statement.
            bool revertedOpen;
            try c.OpenToThePublic() {
                revertedOpen = false;
            } catch {
                revertedOpen = true;
            }
            // If the call reverted, we cannot open; require that caller didn't request opening.
            if (revertedOpen) {
                require(!openPublic);
            }
